import{_ as e,o as n,c as t,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"27. const and volatile Qualifiers","description":"The Little Book of C — 27. const and volatile Qualifiers","frontmatter":{"title":"27. const and volatile Qualifiers","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working with Memory"],"description":"The Little Book of C — 27. const and volatile Qualifiers","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":27,"sidebarWeight":27,"lang":"en-US","alternateEn":"/posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers","alternateZh":"/posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers"},"headers":[],"relativePath":"posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers.md","filePath":"posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers.md"};function o(l,a,p,c,r,d){return n(),t("div",null,[...a[0]||(a[0]=[s(`<p>[中文版本](/posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers)</p><p>C gives you fine-grained control over how variables are used through type qualifiers. Two of the most important are<code>const</code> and<code>volatile</code>. They look simple but play a crucial role in writing safe, predictable, and efficient code, especially in systems programming, embedded systems, and multithreaded environments.</p><h4 id="the-const-qualifier" tabindex="-1">The const Qualifier <a class="header-anchor" href="#the-const-qualifier" aria-label="Permalink to &quot;The const Qualifier&quot;">​</a></h4><p><code>const</code> means read-only: once a variable is initialized, you cannot modify it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const int x = 10;</span></span>
<span class="line"><span>x = 20; // ❌ error: assignment of read-only variable</span></span></code></pre></div><p>It’s a promise to the compiler, and to other programmers, that the value won’t change.</p><p><code>const</code> can be applied to many things:</p><ul><li>Variables</li><li>Function parameters</li><li>Pointers</li><li>Return types</li></ul><h4 id="const-with-pointers" tabindex="-1">const with Pointers <a class="header-anchor" href="#const-with-pointers" aria-label="Permalink to &quot;const with Pointers&quot;">​</a></h4><p><code>const</code> with pointers can be tricky but follows consistent rules. The position of<code>const</code> determines what cannot change.</p><table tabindex="0"><thead><tr><th>Declaration</th><th>Meaning</th></tr></thead><tbody><tr><td><code>const int *p;</code></td><td>Pointer to constant data, data can’t change</td></tr><tr><td><code>int *const p;</code></td><td>Constant pointer, pointer can’t change, data can</td></tr><tr><td><code>const int *const p;</code></td><td>Both pointer and data are constant</td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int value = 42;</span></span>
<span class="line"><span>const int *p1 = &amp;value;   // cannot modify *p1</span></span>
<span class="line"><span>int *const p2 = &amp;value;   // cannot reassign p2</span></span>
<span class="line"><span>const int *const p3 = &amp;value; // cannot change *p3 or p3</span></span></code></pre></div><h4 id="const-in-function-parameters" tabindex="-1">const in Function Parameters <a class="header-anchor" href="#const-in-function-parameters" aria-label="Permalink to &quot;const in Function Parameters&quot;">​</a></h4><p>Marking parameters as<code>const</code> helps prevent accidental modification and enables compiler optimizations.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void print_message(const char *msg) {</span></span>
<span class="line"><span>    printf(&quot;%s\\n&quot;, msg);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here,<code>msg</code> is read-only; the function can’t modify the string it points to.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a program demonstrating<code>const</code> in action:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void show(const int *ptr) {</span></span>
<span class="line"><span>    // *ptr = 10;</span><span> // ❌ not allowed</span></span>
<span class="line"><span>    printf(&quot;Value: %d\\n&quot;, *ptr);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int num = 5;</span></span>
<span class="line"><span>    const int *p = #</span></span>
<span class="line"><span>    int *const q = #</span></span>
<span class="line"><span>    printf(&quot;num = %d\\n&quot;, num);</span></span>
<span class="line"><span>    // *p = 10;</span><span> // ❌ cannot modify value through const pointer</span></span>
<span class="line"><span>    *q = 15;</span><span>   // ✅ data modifiable through q</span></span>
<span class="line"><span>    printf(&quot;num after q change = %d\\n&quot;, num);</span></span>
<span class="line"><span>    show(&amp;num); // function accepts const pointer</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc const_demo.c -o const_demo</span></span>
<span class="line"><span>./const_demo</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>num = 5</span></span>
<span class="line"><span>num after q change = 15</span></span>
<span class="line"><span>Value: 15</span></span></code></pre></div><h4 id="the-volatile-qualifier" tabindex="-1">The volatile Qualifier <a class="header-anchor" href="#the-volatile-qualifier" aria-label="Permalink to &quot;The volatile Qualifier&quot;">​</a></h4><p><code>volatile</code> tells the compiler that a variable can change at any time, even if your code doesn’t modify it. It prevents the compiler from optimizing out reads or writes.</p><p>Use<code>volatile</code> when:</p><ul><li>A variable can be changed by hardware (e.g., memory-mapped I/O registers).</li><li>A variable can be modified by another thread or signal handler.</li><li>You need to force an actual memory read each time, not a cached value.</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>volatile int sensor_value;</span></span>
<span class="line"><span>while (sensor_value &lt; 100) {</span></span>
<span class="line"><span>    // without volatile, compiler might optimize this loop away</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here,<code>sensor_value</code> might be updated by hardware;<code>volatile</code> ensures each check re-reads memory instead of reusing a cached register value.</p><h4 id="combining-const-and-volatile" tabindex="-1">Combining const and volatile <a class="header-anchor" href="#combining-const-and-volatile" aria-label="Permalink to &quot;Combining const and volatile&quot;">​</a></h4><p>Yes, you can use both together, a value that can change unexpectedly, but your code cannot modify it.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const volatile int status_register = 0x1234;</span></span></code></pre></div><p>This is common in embedded systems, where a hardware register’s bits may change due to external events.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><ul><li><code>const</code> improves safety and clarity: makes interfaces self-documenting and helps the compiler catch mistakes.</li><li><code>volatile</code> preserves correctness in concurrent or hardware-driven systems.</li><li>Together, they let you balance optimization with precision, critical in low-level C programming.</li></ul><p>If you misuse or forget them:</p><ul><li>You risk accidental modification of data (<code>const</code>).</li><li>You risk the compiler removing critical reads/writes (<code>volatile</code>).</li></ul><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Write a program that tries to modify a<code>const int</code> through a pointer, observe the compiler error.</p><p>Declare a variable as<code>volatile int counter</code> and increment it in a loop.</p><ul><li>Then remove<code>volatile</code> and inspect the generated assembly with<code>gcc -S</code>.</li></ul><p>Create a function with<code>const char *msg</code> and try to modify it, see why it’s prohibited.</p><p>Experiment with<code>const int *p</code> vs<code>int *const p</code> to understand their difference.</p><p>Combine both:<code>const volatile int flag;</code> and print it in a loop.</p><p>In C,<code>const</code> and<code>volatile</code> are more than just keywords, they’re contracts. They tell the compiler exactly how memory can be used, which helps both humans and machines reason safely about your code.</p>`,48)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
